"""Business logic."""
from app import utils
from app.models import User


def process(data):
    user = User(data["name"])
    return {"user": user.name, "slug": utils.slugify(user.name)}


def _unused_helper(values):
    return [v * 2 for v in values]


class Report:
    def __init__(self, data):
        self.data = data

    def render(self):
        return f"{self.data['user']} ({self.data['slug']})"

    def never_called(self):
        return None

